function Assert-True {
    param(
        [Parameter(Mandatory = $true)][bool]$Condition,
        [Parameter(Mandatory = $true)][string]$Message
    )

    if (-not $Condition) {
        throw $Message
    }
}

function Get-FunctionBody {
    param(
        [Parameter(Mandatory = $true)][string]$Text,
        [Parameter(Mandatory = $true)][string]$Name
    )

    $pattern = "(?ms)^(?:static\s+)?func $([regex]::Escape($Name))\b.*?(?=^(?:static\s+)?func |\z)"
    $match = [regex]::Match($Text, $pattern)
    Assert-True $match.Success "Could not find function $Name."
    $match.Value
}

function Get-ClassBody {
    param(
        [Parameter(Mandatory = $true)][string]$Text,
        [Parameter(Mandatory = $true)][string]$Name
    )

    $pattern = "(?ms)^class $([regex]::Escape($Name)):\s*\r?\n.*?(?=^(?:class |const |var |func )|\z)"
    $match = [regex]::Match($Text, $pattern)
    Assert-True $match.Success "Could not find class $Name."
	$match.Value
}

function Get-ExportPresetBlock {
	param(
		[Parameter(Mandatory = $true)][string]$Text,
		[Parameter(Mandatory = $true)][string]$Name
	)

	$pattern = '(?ms)^\[preset\.\d+\]\s*\r?\n(?:(?!^\[preset\.\d+\]).)*?^name="' + [regex]::Escape($Name) + '"(?:(?!^\[preset\.\d+\]).)*'
	$match = [regex]::Match($Text, $pattern)
	Assert-True $match.Success "Could not find export preset $Name."
	$match.Value
}

