Assert-True ($main -match 'const DESKTOP_TARGET_FRAME_RATE := 120') "Desktop target frame rate should allow smooth 120 FPS on high-refresh displays."
Assert-True ($main -match 'const MOBILE_TARGET_FRAME_RATE := 60') "Mobile target frame rate should stay capped at smooth 60 FPS."
Assert-True ($main -match 'const MOBILE_IDLE_FRAME_RATE := 30') "Mobile idle battery governor should cap quiet screens at 30 FPS."
$screenCappedFrameRate = Get-FunctionBody $main "_screen_capped_frame_rate"
Assert-True ($screenCappedFrameRate -match 'return mini\(refresh_rate, frame_cap\) if refresh_rate > 0 else frame_cap') "Frame-rate helper should not exceed the requested cap or screen refresh."
$configurePerformanceMode = Get-FunctionBody $main "_configure_performance_mode"
Assert-True ($configurePerformanceMode -match '_apply_performance_cap\(_mobile_active_frame_rate\(\), false\)') "Mobile performance boot should start at the smooth active frame cap."
Assert-True ($configurePerformanceMode -match '_apply_performance_cap\(_screen_capped_frame_rate\(DESKTOP_TARGET_FRAME_RATE\), false\)') "Desktop refresh handling should target up to 120 FPS without exceeding the screen refresh."
$batteryGovernor = Get-FunctionBody $main "_process_battery_governor"
Assert-True ($batteryGovernor -match '_mobile_idle_frame_rate\(\) if idle else _mobile_active_frame_rate\(\)') "Battery governor should switch between idle and active mobile frame caps."
Assert-True ($main -match 'const DETAIL_HEADER_GAUGE_REFRESH_SECONDS := 0\.05') "Skill detail header gauges should accept new targets at a capped cadence."
Assert-True ($main -match 'const ACTION_CARD_TITLE_OUTLINE_SIZE := 34') "Action card titles should retain the original readable outline while perf work happens elsewhere."
Assert-True ($main -match 'const ACTION_CARD_FACE_BORDER_ENABLED := true') "Action cards should keep their clean face outline above the restored depth slab."
Assert-True ($main -match 'const ACTION_CARD_SIMPLE_BACKGROUND_ENABLED := false') "Normal action cards should keep rounded masked backgrounds; texture prewarm should carry the performance load."
Assert-True ($main -match 'const ACTION_CARD_FACE_RADIUS := 66\.0') "Action card face, background, and depth corners should share one radius."
Assert-True ($main -match 'const ACTION_CARD_FACE_BORDER_Z_INDEX := 244') "Action card face borders should draw above progress rails to preserve an uninterrupted stroke."
Assert-True ($main -match 'const ACTION_CARD_3D_DEPTH_OFFSET := Vector2\(28\.0, 34\.0\)') "Action cards should keep a visible but modest 3D depth slab."
Assert-True ($main -match 'const ACTION_CARD_3D_PRESS_OFFSET := Vector2\(28\.0, 34\.0\)') "Action card press feedback should seat the face fully onto the 3D depth slab."
Assert-True ($main -match 'const SCRAPWOOD_MAT_ICON_TEXTURE := "res://assets/content/icons/resources/scrapwood\.png"') "Scrapwood mats should use the selected Scrapwood resource icon."
Assert-True ($main -match 'const SOFTWOOD_MAT_ICON_TEXTURE := "res://assets/content/icons/resources/softwood\.png"') "Softwood mats should use the selected single-log Softwood resource icon."
Assert-True ($main -match 'const HARDWOOD_MAT_ICON_TEXTURE := "res://assets/content/icons/resources/hardwood\.png"') "Hardwood mats should use the selected stacked-log Hardwood resource icon."
Assert-True ($main -match 'const HONEY_MAT_ICON_TEXTURE := "res://assets/content/icons/resources/honey\.png"') "Honey mats should use the selected hand-and-honey icon texture."
Assert-True ($main -match 'const MAT_COLLECTION_STONE_BACKGROUND_TEXTURE := "res://assets/content/ui/mats/mat-bg-stone\.png"') "Mat collection modules should have the selected stone background asset available."
Assert-True ($main -match 'const MAT_COLLECTION_WOOD_BACKGROUND_TEXTURE := "res://assets/content/ui/mats/mat-bg-wood\.png"') "Wood-style mat collection modules should have a wood background asset."
Assert-True ($main -match 'const MAT_COLLECTION_MODULE_SIZE := Vector2\(754, 754\)') "Mat collection modules should be square and match normal action module height."
Assert-True ($main -match '"cost_currencies": \["softwood", "softwood", "hardwood", "hardwood"\]') "Hub build costs should support early Softwood tiers and later Hardwood tiers."
Assert-True ($main -match 'func _hub_module_wood_currency_for_level\(module_id: String, level: int\) -> String:') "Hub build costs should resolve wood currency by upgrade tier."
$viewportBufferMatch = [regex]::Match($main, 'const DETAIL_LAZY_VIEWPORT_BUFFER_PX := ([0-9]+(?:\.[0-9]+)?)')
Assert-True $viewportBufferMatch.Success "Missing skill detail lazy viewport buffer."
Assert-True ([double]$viewportBufferMatch.Groups[1].Value -le 120.0) "Skill detail should not mount a large offscreen card buffer while idle."
$initialMountMatch = [regex]::Match($main, 'const DETAIL_LAZY_INITIAL_FORCE_MOUNT_COUNT := (\d+)')
Assert-True $initialMountMatch.Success "Missing skill detail initial lazy mount limit."
Assert-True ([int]$initialMountMatch.Groups[1].Value -le 4) "Skill detail should not eagerly mount more than four initial activity cards."
$fishingInitialMountMatch = [regex]::Match($main, 'const FISHING_DETAIL_LAZY_INITIAL_FORCE_MOUNT_COUNT := (\d+)')
Assert-True $fishingInitialMountMatch.Success "Missing fishing detail initial lazy mount limit."
Assert-True ([int]$fishingInitialMountMatch.Groups[1].Value -le 4) "Fishing detail should not synchronously mount the full page before first interaction."
$processDetailLazyWindow = Get-FunctionBody -Text $main -Name "_process_detail_lazy_window"
Assert-True ($processDetailLazyWindow -notmatch '_fishing_rework_active_for_skill\(selected_skill_id\) and _detail_lazy_all_mounted\(\)[\s\S]*?return 0') "Fishing detail lazy-window scans must keep pruning instead of exiting after every module has been mounted once."
$detailLazyCanBuildOffscreenCachedEntry = Get-FunctionBody -Text $main -Name "_detail_lazy_can_build_offscreen_cached_entry"
Assert-True ($detailLazyCanBuildOffscreenCachedEntry -match '_fishing_rework_active_for_skill\(skill_id\)[\s\S]*return false') "Fishing detail should not build offscreen cached module trees."
$detailLazyAllMounted = Get-FunctionBody -Text $main -Name "_detail_lazy_all_mounted"
Assert-True ($main -match 'var detail_lazy_all_mounted_cache_frame := -1') "Detail lazy all-mounted checks should keep a per-frame cache."
Assert-True ($detailLazyAllMounted -match 'Engine\.get_process_frames\(\)[\s\S]*detail_lazy_all_mounted_cache_frame == current_frame') "Detail lazy all-mounted checks should reuse same-frame results instead of rescanning the plan."
$fishingDetailRouteInput = Get-FunctionBody -Text $main -Name "_route_fishing_detail_input"
Assert-True ($fishingDetailRouteInput -match '_try_handoff_fishing_deferred_vertical_scroll\(event, event_position\)[\s\S]*?_fishing_detail_plain_scroll_motion_can_skip_global_hit_tests\(event, event_position\)[\s\S]*?_route_fishing_area_pin_corner_input\(event\)') "Fishing drag motion should skip global button hit-tests after vertical-scroll handoff has first chance."
Assert-True ($fishingDetailRouteInput -match '_route_active_fishing_control_drag_handoff\(event\)[\s\S]*?_try_handoff_fishing_deferred_vertical_scroll\(event, event_position\)') "Fishing drags that start on a location tile or offer should hand off before generic fishing hit-tests."
$activeFishingControlDragHandoff = Get-FunctionBody -Text $main -Name "_route_active_fishing_control_drag_handoff"
